// Framework-free core of the [hl]/[code] highlighter. Shared by the full CodeBlocks
// bundle (src/plugins/highlight.ts) and the standalone highlight bundle
// (src/highlightOnly.ts), so it must not import Vue or anything that runs author code.
import hljs from 'highlight.js/lib/core'
//import 'highlight.js/styles/ocean.css'
import 'highlight.js/styles/tomorrow.css'
import '../styles/highlight.styl'

hljs.configure({ useBR: false })

import cpp from 'highlight.js/lib/languages/cpp'
import csharp from 'highlight.js/lib/languages/csharp'
import css from 'highlight.js/lib/languages/css'
import fortran from 'highlight.js/lib/languages/fortran'
import glsl from 'highlight.js/lib/languages/glsl'
import java from 'highlight.js/lib/languages/java'
import javascript from 'highlight.js/lib/languages/javascript'
import perl from 'highlight.js/lib/languages/perl'
import php from 'highlight.js/lib/languages/php'
import python from 'highlight.js/lib/languages/python'
import r from 'highlight.js/lib/languages/r'
import { whenMathJaxReady } from '@/lib/mathjax'

hljs.registerLanguage('c', cpp)
hljs.registerLanguage('c++', cpp)
hljs.registerLanguage('c#', csharp)
hljs.registerLanguage('css', css)
hljs.registerLanguage('fortran', fortran)
hljs.registerLanguage('glsl', glsl)
hljs.registerLanguage('java', java)
hljs.registerLanguage('javascript', javascript)
hljs.registerLanguage('perl', perl)
hljs.registerLanguage('php', php)
hljs.registerLanguage('python', python)
hljs.registerLanguage('r', r)

const reg_hl = /(\[hl\]|\[hl\s+language="?(.*?)"?\])(.*?)(\[\/hl\])/gm
const reg_code = /(\[code\]|\[code\s+language="?(.*?)"?\])([\s\S]*?)(\[\/code\])/gm

export interface IHighlightProcessor {
    processElements(scope?: Document | HTMLElement, inLang?: string): void
    processElementSimple(el: HTMLElement, inLang: string | undefined): void
    processElement(el: HTMLElement, inLang: string | undefined): void
}

export const highlightProcessor: IHighlightProcessor = {
    processElements: function (
        scope: Document | HTMLElement | undefined,
        inLang: string | undefined
    ) {
        if (scope === undefined) {
            scope = document
        }
        const elements = scope.querySelectorAll('[highlight]')
        elements.forEach((el) => {
            if (inLang === undefined && el.hasAttribute('highlight')) {
                const lang = el.getAttribute('highlight')
                inLang = lang === null ? undefined : lang
            }
            highlightProcessor.processElement(el as HTMLElement, inLang)
        })
    },
    // Replaces the markup on the innerHTML string level, so DOM objects attached to
    // children of `el` are lost.
    processElementSimple(el: HTMLElement, inLang: string | undefined) {
        if (inLang === undefined && el.hasAttribute('highlight')) {
            const lang = el.getAttribute('highlight')
            inLang = lang === null ? 'javascript' : lang
        }

        let txt = el.innerHTML.replace(reg_hl, function (m1, m2, m3, m4, m5) {
            const lang = m3 === undefined ? inLang : m3
            //console.log("m1", m1, "m2", m2, "m3", m3, "m4", m4, "m5", m5, "in", inLang, "res", lang)
            if (lang) {
                return '<span is-code>' + hljs.highlight(lang, m4).value + '</span>'
            } else {
                return '<span is-code>' + hljs.highlightAuto(m4).value + '</span>'
            }
        })

        txt = txt.replace(reg_code, function (m1, m2, m3, m4, m5) {
            const lang = m3 === undefined ? inLang : m3
            m4 = m4
                .replace(/<br( +\/)?>/g, '\n')
                .replace(/&nbsp;/g, ' ')
                .replace(/&lt;/g, '<')
                .replace(/&gt;/g, '>')
                .replace(/&amp;/g, '&')
                .replace(/&#38;/g, '&')

            if (lang) {
                return '<pre is-code>' + hljs.highlight(lang, m4).value + '</pre>'
            } else {
                return '<pre is-code>' + hljs.highlightAuto(m4).value + '</pre>'
            }
        })

        el.innerHTML = txt
    },
    processElement(el: HTMLElement, inLang: string | undefined) {
        whenMathJaxReady(() => highlightProcessor.processElementSimple(el, inLang))
    },
}

export default hljs
