// Standalone entry for pages that only need the [hl]/[code] syntax highlighting of
// CodeBlocks (e.g. the ILIAS question text outside the sandboxed codeblocks iframe).
// Built by vite.highlight.config.js into js/codeblocks-js/codeblocks-highlight.iife.js
// (+ codeblocks-highlight.css). It deliberately contains no Vue, no compilers and
// nothing that executes author code: highlight.js only produces escaped markup.
import { highlightProcessor } from '@/plugins/highlightCore'

export interface ICodeblocksHighlight {
    /**
     * Highlights the [hl]…[/hl] and [code language=…]…[/code] markup inside every element
     * with a `highlight` attribute below `scope` (default: document). `lang` overrides the
     * language given by the `highlight` attribute. Waits for MathJax startup if MathJax
     * is present on the page (MathJax 2 and 3), otherwise runs immediately.
     *
     * Unlike hljs.$vue.processElements of the full bundle, the language of the first
     * element does not leak into the following ones: without `lang` every element uses
     * its own `highlight` attribute (pages may show several questions).
     */
    processElements(scope?: Document | HTMLElement, lang?: string): void
}

const api: ICodeblocksHighlight = Object.freeze({
    processElements(scope?: Document | HTMLElement, lang?: string): void {
        const root = scope ?? document
        root.querySelectorAll<HTMLElement>('[highlight]').forEach((el) => {
            highlightProcessor.processElement(el, lang ?? el.getAttribute('highlight') ?? undefined)
        })
    },
})

declare global {
    interface Window {
        codeblocksHighlight: ICodeblocksHighlight
    }
}

window.codeblocksHighlight = api

export default api
